create extension if not exists pgcrypto;
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),name text not null,category text not null,address text not null,lat double precision,lng double precision,rating numeric(2,1) default 0,verified boolean default false,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses(id) on delete cascade,name text not null,description text,price numeric(12,2));
create table if not exists public.inventory(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,status text not null default 'UNKNOWN',quantity integer,checked_at timestamptz);
create table if not exists public.user_search_confirmations(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,business_id uuid references public.businesses(id) on delete cascade,request_text text not null,status text not null default 'PENDING',created_at timestamptz default now(),responded_at timestamptz);
create table if not exists public.plans(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,monthly_price numeric(12,2) not null,annual_price numeric(12,2) not null,trial_days int default 7,active boolean default true);
insert into public.plans(code,name,monthly_price,annual_price) values('essencial','NEXA Essencial',19.90,199),('profissional','NEXA Profissional',39.90,399),('premium','NEXA Premium',69.90,699) on conflict(code) do nothing;
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,plan_id uuid references public.plans(id),provider text default 'stripe',provider_subscription_id text,status text not null default 'trialing',current_period_end timestamptz,created_at timestamptz default now());
create or replace function public.nexa_search(search_text text,user_lat double precision default null,user_lng double precision default null) returns table(id uuid,name text,category text,address text,lat double precision,lng double precision,rating numeric,open boolean,availability text,distance double precision) language sql security definer as $$ select b.id,b.name,b.category,b.address,b.lat,b.lng,b.rating,true,case when exists(select 1 from products p join inventory i on i.product_id=p.id where p.business_id=b.id and i.status='CONFIRMED') then 'CONFIRMADO' when exists(select 1 from products p join inventory i on i.product_id=p.id where p.business_id=b.id and i.status='PROBABLE') then 'PROVÁVEL' else 'NÃO CONFIRMADO' end,case when user_lat is not null and user_lng is not null and b.lat is not null and b.lng is not null then 6371*acos(least(1,greatest(-1,sin(radians(user_lat))*sin(radians(b.lat))+cos(radians(user_lat))*cos(radians(b.lat))*cos(radians(b.lng-user_lng))))) end from public.businesses b where lower(b.name||' '||b.category) like '%'||lower(search_text)||'%' or lower(search_text) like '%'||lower(b.category)||'%' order by b.verified desc,b.rating desc nulls last limit 30 $$;
alter table public.businesses enable row level security;alter table public.products enable row level security;alter table public.inventory enable row level security;alter table public.plans enable row level security;alter table public.user_search_confirmations enable row level security;
create policy "public businesses read" on public.businesses for select using(true);create policy "public products read" on public.products for select using(true);create policy "public inventory read" on public.inventory for select using(true);create policy "public plans read" on public.plans for select using(true);create policy "users create confirmations" on public.user_search_confirmations for insert with check(auth.uid()=user_id);create policy "users read own confirmations" on public.user_search_confirmations for select using(auth.uid()=user_id);